/**
 * Windows-only: give the app window its icon (top-left caption + taskbar).
 *
 * Electrobun 1.18.1 exposes no window-icon API and never sets one, so the native
 * window shows the default blank icon even though we embed an icon in the exe.
 * We reach the window the same way as the dark title-bar workaround (FindWindowW
 * by title) and set WM_SETICON (small + big) plus the class icons via Win32 FFI.
 * The .ico is embedded here (base64) so there is no runtime file dependency; it is
 * written to a temp file for LoadImageW. Any failure is a silent no-op.
 *
 * GENERATED by scratchpad/gen-window-icon.ts from assets/icon.ico — do not edit
 * the base64 by hand; re-run that script after changing the icon.
 */
import { tmpdir } from "node:os";
import { join } from "node:path";
import { writeFileSync } from "node:fs";

const ICON_ICO_BASE64 =
  "";

export function applyWindowsWindowIcon(windowTitle: string): void {
  if (process.platform !== "win32") return;

  try {
    const { dlopen, ptr } = require("bun:ffi");

    const icoPath = join(tmpdir(), "logicgatt-window-icon.ico");
    writeFileSync(icoPath, Buffer.from(ICON_ICO_BASE64, "base64"));

    const user32 = dlopen("user32.dll", {
      FindWindowW: { args: ["ptr", "ptr"], returns: "ptr" },
      LoadImageW: { args: ["ptr", "ptr", "u32", "i32", "i32", "u32"], returns: "ptr" },
      SendMessageW: { args: ["ptr", "u32", "u64", "ptr"], returns: "ptr" },
      SetClassLongPtrW: { args: ["ptr", "i32", "ptr"], returns: "ptr" },
    });

    const IMAGE_ICON = 1;
    const LR_LOADFROMFILE = 0x0010;
    const WM_SETICON = 0x0080;
    const ICON_SMALL = 0n;
    const ICON_BIG = 1n;
    const GCLP_HICON = -14;
    const GCLP_HICONSM = -34;

    const pathBuf = Buffer.from(icoPath + "\0", "utf16le");
    const hBig = user32.symbols.LoadImageW(null, ptr(pathBuf), IMAGE_ICON, 32, 32, LR_LOADFROMFILE);
    const hSmall = user32.symbols.LoadImageW(null, ptr(pathBuf), IMAGE_ICON, 16, 16, LR_LOADFROMFILE);
    if (!hBig && !hSmall) {
      console.warn("window icon: LoadImageW returned null");
      return;
    }

    const titleBuf = Buffer.from(windowTitle + "\0", "utf16le");
    let attempts = 0;
    const apply = () => {
      attempts++;
      const hwnd = user32.symbols.FindWindowW(null, ptr(titleBuf));
      if (hwnd) {
        if (hSmall) {
          user32.symbols.SendMessageW(hwnd, WM_SETICON, ICON_SMALL, hSmall);
          user32.symbols.SetClassLongPtrW(hwnd, GCLP_HICONSM, hSmall);
        }
        if (hBig) {
          user32.symbols.SendMessageW(hwnd, WM_SETICON, ICON_BIG, hBig);
          user32.symbols.SetClassLongPtrW(hwnd, GCLP_HICON, hBig);
        }
        console.log(`[window-icon] applied (hwnd found after ${attempts} attempt(s))`);
        return;
      }
      if (attempts < 30) setTimeout(apply, 100);
      else console.warn("[window-icon] window not found after 30 attempts — icon not set");
    };
    apply();
  } catch (err) {
    console.warn(`window icon not applied: ${err instanceof Error ? err.message : String(err)}`);
  }
}
